var i=`fault-tolerance`;var n=97;var r={en:[{id:`T097-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Fault Tolerance`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`IaC defines infrastructure resources in version-controlled declarations or programs.`},{id:`B`,text:`Observability allows engineers to infer a system's internal state from emitted evidence.`},{id:`C`,text:`Fault tolerance lets a system continue delivering acceptable behavior when components fail.`},{id:`D`,text:`An SLI is a quantitative service reliability indicator; an SLO is a target for that indicator; an SLA is a contractual commitment, often with consequences.`}]},{id:`T097-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Fault Tolerance`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Plan changes before applying them, use state and drift detection, separate environments, and keep secrets outside source.`},{id:`B`,text:`Design health and readiness signals, connection draining, retries, sticky sessions only when necessary, and proxy timeout behavior.`},{id:`C`,text:`Define which failures to tolerate: instance crash, zone loss, timeout, bad data or dependency unavailability.`},{id:`D`,text:`Build reproducibly, run fast quality gates first, protect branches and secrets, and promote the same verified artifact across environments.`}]},{id:`T097-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Fault Tolerance`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`A booking API releases 5% of requests to a new pricing flow, compares error rate and latency, then expands or rolls back. Feature flags may separately control exposure of new business behavior.`},{id:`B`,text:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`},{id:`C`,text:`A booking request can be traced through API, payment provider and database, while a metric counts failed confirmations and logs record sanitized error context for diagnosis.`},{id:`D`,text:`An API can add replicas during seasonal booking spikes, but a shared database with an inefficient query may remain the bottleneck. Queue-based workers can scale by backlog when tasks are independent.`}]},{id:`T097-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Fault Tolerance`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`A healthy process is not necessarily ready for traffic.`},{id:`B`,text:`Redundant replicas sharing one database or cloud zone may share the same failure mode.`},{id:`C`,text:`An SLA target should not be copied blindly into internal SLOs.`},{id:`D`,text:`More logs do not mean better visibility.`}]},{id:`T097-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It combines redundancy, isolation, graceful degradation, recovery and explicit fault assumptions.`}]}]},{id:`T097-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Fault tolerance means a system can never experience any partial failure.`}]}]},{id:`T097-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Graceful degradation must never compromise payment correctness or access control.`}]}]},{id:`T097-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Fault Tolerance`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Define which failures to tolerate: instance crash, zone loss, timeout, bad data or dependency unavailability.`},{id:`B`,text:`A fallback that silently returns incorrect prices is always preferable to failure.`},{id:`C`,text:`Fault tolerance lets a system continue delivering acceptable behavior when components fail.`},{id:`D`,text:`An SLA and an SLO are always the same internal engineering metric.`}]},{id:`T097-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Fault Tolerance`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`},{id:`B`,text:`Graceful degradation must never compromise payment correctness or access control.`},{id:`C`,text:`Fault tolerance means a system can never experience any partial failure.`},{id:`D`,text:`Deployment and release are necessarily one irreversible action.`}]},{id:`T097-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to configure a load-balancing design for HTTP and WebSocket traffic, specifying readiness, graceful shutdown, retries and uneven request costs.`},{id:`B`,text:`Ask an agent to model failures of mail, cache and database dependencies separately and define degraded behavior, recovery tests and observability.`},{id:`C`,text:`Ask an agent to define booking-confirmation SLIs, a measurable SLO, alert thresholds and an error-budget policy. Verify the measurement excludes only justified cases.`},{id:`D`,text:`Ask an agent to instrument booking confirmation with spans, metrics and structured logs. Require a troubleshooting walkthrough for one slow request and one failed payment.`}]},{id:`T097-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which dependencies are safe to degrade and which must fail closed?`}]}]},{id:`T097-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Fault Tolerance`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T097-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`,b:!0},{t:` — propose three checks for `},{t:`Fault Tolerance`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T097-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T097-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Fault Tolerance`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A booking service continues accepting reservation searches when email is down, queues receipts for later and prevents email failure from undoing confirmed reservations.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T097-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Відмовостійкість`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`IaC визначає інфраструктуру через версіоновані декларації чи програми.`},{id:`B`,text:`Спостережуваність дозволяє визначати внутрішній стан системи за її сигналами.`},{id:`C`,text:`Відмовостійкість дозволяє системі продовжувати прийнятну роботу за відмови компонентів.`},{id:`D`,text:`SLI — кількісний показник надійності; SLO — його цільове значення; SLA — договірне зобов’язання, часто із наслідками невиконання.`}]},{id:`T097-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Відмовостійкість`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Плануйте зміни до застосування, використовуйте state й пошук drift, ізолюйте середовища та тримайте секрети поза кодом.`},{id:`B`,text:`Налаштуйте health/readiness, connection draining, повтори, sticky sessions лише за потреби та proxy timeout.`},{id:`C`,text:`Визначте допустимі відмови: падіння інстансу, зони, timeout, некоректні дані чи недоступність залежності.`},{id:`D`,text:`Забезпечуйте відтворювані збірки, запускайте швидкі перевірки першими, захищайте гілки й секрети та просувайте один перевірений артефакт між середовищами.`}]},{id:`T097-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Відмовостійкість`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`API бронювань надає новому ціновому сценарію 5% запитів, порівнює помилки й затримку, потім розширює частку або відкочується. Feature flag може окремо керувати новою поведінкою.`},{id:`B`,text:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`},{id:`C`,text:`Запит бронювання відстежується через API, платіжний провайдер і БД; метрика рахує невдалі підтвердження, а лог зберігає очищений контекст помилки.`},{id:`D`,text:`API може додавати репліки під час сезонного напливу бронювань, але спільна БД із поганим запитом лишиться вузьким місцем. Воркери черги масштабуються за backlog для незалежних задач.`}]},{id:`T097-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Відмовостійкість`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Живий процес не обов’язково готовий до трафіку.`},{id:`B`,text:`Резервні репліки зі спільною БД чи зоною хмари можуть мати спільну точку відмови.`},{id:`C`,text:`SLA не потрібно сліпо переносити в SLO.`},{id:`D`,text:`Більше логів не завжди означає кращу діагностику.`}]},{id:`T097-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Вона поєднує резервування, ізоляцію, деградацію, відновлення й модель можливих збоїв.`}]}]},{id:`T097-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Відмовостійкість означає, що система ніколи не має часткових збоїв.`}]}]},{id:`T097-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Деградація не повинна порушувати коректність платежів чи права доступу.`}]}]},{id:`T097-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Відмовостійкість`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Визначте допустимі відмови: падіння інстансу, зони, timeout, некоректні дані чи недоступність залежності.`},{id:`B`,text:`Fallback із непомітно хибними цінами завжди кращий за помилку.`},{id:`C`,text:`Відмовостійкість дозволяє системі продовжувати прийнятну роботу за відмови компонентів.`},{id:`D`,text:`SLA і SLO — це завжди одна й та сама внутрішня метрика.`}]},{id:`T097-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Відмовостійкість`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`},{id:`B`,text:`Деградація не повинна порушувати коректність платежів чи права доступу.`},{id:`C`,text:`Відмовостійкість означає, що система ніколи не має часткових збоїв.`},{id:`D`,text:`Розгортання та випуск функції обов’язково одна незворотна дія.`}]},{id:`T097-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента спроєктувати балансування HTTP та WebSocket, визначити readiness, graceful shutdown, повтори та нерівну ціну запитів.`},{id:`B`,text:`Попросіть агента окремо змоделювати збої пошти, кешу й БД та визначити деградацію, тести відновлення й моніторинг.`},{id:`C`,text:`Попросіть агента визначити SLI підтвердження бронювань, вимірюваний SLO, пороги alert і політику error budget. Перевірте обґрунтованість усіх винятків.`},{id:`D`,text:`Попросіть агента інструментувати підтвердження бронювання spans, метриками та структурованими логами. Вимагайте сценарій діагностики повільного запиту та збою платежу.`}]},{id:`T097-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які залежності можна деградувати, а які мають завершуватися відмовою?`}]}]},{id:`T097-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Відмовостійкість`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T097-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Відмовостійкість`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T097-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T097-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Відмовостійкість`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Сервіс бронювань продовжує пошук, коли email недоступний, ставить квитанції в чергу й не скасовує підтверджені бронювання через збій листів.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var a={slug:i,topicId:97,questions:r};export{a as default,r as questions,i as slug,n as topicId};